using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Net;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;
[assembly:System.Reflection.AssemblyTitle("Bagaceira · Gerenciador online")]
[assembly:System.Reflection.AssemblyVersion("2.0.1.0")]
sealed class AdminSettings {public string Service {get;set;}public string Secret {get;set;}}
sealed class DeviceRow {public string code {get;set;}public string name {get;set;}public string status {get;set;}public long? last_seen {get;set;}public string StateText {get{return status=="allowed"?"Liberado":status=="blocked"?"Bloqueado":"Aguardando";}}}
sealed class DeviceList {public DeviceRow[] devices {get;set;}}
sealed class AdminForm:Form {
 TextBox service=new TextBox(),secret=new TextBox(),code=new TextBox(),name=new TextBox();DataGridView grid=new DataGridView();Label status=new Label();Button connect,allow,block;bool working;
 string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BagaceiraAdmin","online-config.dat");
 AdminForm(){Text="Bagaceira · Gerenciador online";ClientSize=new Size(850,570);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",9);BackColor=Color.FromArgb(12,16,19);ForeColor=Color.White;Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);
  Add("Servidor HTTPS",18,16,150);service.SetBounds(18,40,500,25);service.AccessibleName="Servidor HTTPS";
  Add("Chave administrativa",535,16,280);secret.SetBounds(535,40,295,25);secret.UseSystemPasswordChar=true;secret.AccessibleName="Chave administrativa";
  connect=Button("Conectar / atualizar",18,80,200,async()=>await RefreshList());
  Button("Painel online",230,80,180,()=>{try{System.Diagnostics.Process.Start(Host()+"/admin");}catch(Exception ex){status.Text=ex.Message;}return Task.FromResult(0);});
  Button("Copiar chave",630,80,200,()=>{try{if(secret.Text.Length>0){Clipboard.SetText(secret.Text);status.Text="Chave administrativa copiada. Use somente no seu painel online.";}}catch{status.Text="Não foi possível copiar a chave.";}return Task.FromResult(0);});
  Add("PCs cadastrados: selecione uma linha ou cole o código recebido.",18,128,800);
  grid.SetBounds(18,154,812,230);grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.MultiSelect=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AutoGenerateColumns=false;grid.BackgroundColor=Color.FromArgb(20,28,33);grid.ForeColor=Color.Black;grid.RowHeadersVisible=false;
  grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Nome",DataPropertyName="name",Width=180});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Estado",DataPropertyName="StateText",Width=100});grid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="Código do PC",DataPropertyName="code",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill});
  grid.SelectionChanged+=(s,e)=>{var row=grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as DeviceRow;if(row!=null){code.Text=row.code;name.Text=row.name;}};
  Add("Código do PC",18,399,550);code.SetBounds(18,424,812,25);code.AccessibleName="Código do PC";
  Add("Nome da pessoa",18,463,200);name.SetBounds(18,488,355,26);name.AccessibleName="Nome da pessoa";name.MaxLength=100;
  allow=Button("Liberar PC",400,486,200,async()=>await SetState("allowed"));block=Button("Bloquear PC",615,486,215,async()=>await SetState("blocked"));
  status.SetBounds(18,533,812,30);status.ForeColor=Color.Cyan;status.Text="Configure o servidor para liberar e bloquear computadores.";
  Controls.AddRange(new Control[]{service,secret,grid,code,name,status});
  try{if(File.Exists(path)){var settings=new JavaScriptSerializer().Deserialize<AdminSettings>(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(path),null,DataProtectionScope.CurrentUser)));service.Text=settings.Service;secret.Text=settings.Secret;}}catch{status.Text="Reconfigure o acesso administrativo nesta conta Windows.";}
 }
 void Add(string text,int x,int y,int width){Controls.Add(new Label{Text=text,Left=x,Top=y,Width=width,Height=23});}
 Button Button(string text,int x,int y,int width,Func<Task> action){var b=new Button{Text=text,Left=x,Top=y,Width=width,Height=32,ForeColor=Color.Cyan,BackColor=Color.FromArgb(0,48,57),FlatStyle=FlatStyle.Flat};b.FlatAppearance.BorderColor=Color.Cyan;b.Click+=async(s,e)=>await action();Controls.Add(b);return b;}
 string Host(){Uri url;if(!Uri.TryCreate(service.Text.Trim(),UriKind.Absolute,out url)||url.Scheme!="https"||!url.IsDefaultPort||url.AbsolutePath!="/"||url.Query!=""||url.Fragment!=""||url.UserInfo!="")throw new InvalidDataException("Informe a origem HTTPS do seu servidor.");if(secret.Text.Length<32)throw new InvalidDataException("Informe a chave administrativa fornecida na configuração do servidor.");return url.GetLeftPart(UriPartial.Authority);}
 async Task<T> Request<T>(string route,object payload){string host=Host(),key=secret.Text;return await Task.Run(()=>{ServicePointManager.SecurityProtocol|=(SecurityProtocolType)3072;var r=(HttpWebRequest)WebRequest.Create(host+route);r.Method=payload==null?"GET":"POST";r.Timeout=r.ReadWriteTimeout=15000;r.AllowAutoRedirect=false;r.Headers[HttpRequestHeader.Authorization]="Bearer "+key;if(payload!=null){byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(payload));r.ContentType="application/json";r.ContentLength=bytes.Length;using(var s=r.GetRequestStream())s.Write(bytes,0,bytes.Length);}using(var response=(HttpWebResponse)r.GetResponse())using(var stream=response.GetResponseStream())using(var memory=new MemoryStream()){byte[] b=new byte[4096];int n;while((n=stream.Read(b,0,b.Length))>0){if(memory.Length+n>512000)throw new IOException("Resposta muito grande.");memory.Write(b,0,n);}return new JavaScriptSerializer().Deserialize<T>(Encoding.UTF8.GetString(memory.ToArray()));}});}
 void Busy(bool value){working=value;connect.Enabled=allow.Enabled=block.Enabled=!value;service.Enabled=secret.Enabled=!value;}
 async Task RefreshList(){if(working)return;Busy(true);try{var data=await Request<DeviceList>("/v1/admin/devices",null);grid.DataSource=data.devices;Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,ProtectedData.Protect(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new AdminSettings{Service=Host(),Secret=secret.Text})),null,DataProtectionScope.CurrentUser));status.Text="Conectado · "+data.devices.Length+" PC(s). Liberados consultam a cada 5 minutos; offline têm até 24 horas.";}catch(Exception ex){status.Text="Não foi possível conectar: "+ex.Message;}finally{Busy(false);}}
 async Task SetState(string value){if(working)return;if(!Regex.IsMatch(code.Text.Trim(),@"\ABGC2-[A-F0-9]{64}\z")){status.Text="Cole o novo código BGC2 do computador.";return;}string device=code.Text.Trim(),label=name.Text;Busy(true);bool ok=false;try{await Request<object>("/v1/admin/device",new{device=device,status=value,name=label});ok=true;status.Text=value=="allowed"?"Computador liberado.":"Computador bloqueado. Conectado: próxima consulta em até 5 minutos; offline: até terminar a tolerância.";}catch(Exception ex){status.Text="Não foi possível alterar: "+ex.Message;}finally{Busy(false);}if(ok){string message=status.Text;await RefreshList();status.Text=message;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new AdminForm());}
}
